package com.slotmind.service; import com.slotmind.entity.*; import com.slotmind.enums.*; import com.slotmind.exception.ApiExceptions.*; import com.slotmind.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class SlotService { final SlotRepository repo; final WorkflowService workflow; public SlotService(SlotRepository r,WorkflowService w){repo=r;workflow=w;} public List<Slot> list(){return repo.findAll();} public Slot status(String id,SlotStatus s){Slot x=repo.findById(id).orElseThrow(()->new NotFound("Slot not found"));if(s==SlotStatus.OPEN&&x.getStatus()==SlotStatus.CANCELLED)throw new Conflict("Cancelled slot cannot be reopened");if(s==SlotStatus.BOOKED&&x.getStatus()!=SlotStatus.BOOKED)throw new Conflict("Only the booking workflow can book a slot");if(x.getStatus()==SlotStatus.CANCELLED&&s!=SlotStatus.CANCELLED)throw new Conflict("Cancelled slot cannot change status");x.setStatus(s);Slot saved=repo.save(x);if(s==SlotStatus.CANCELLED)workflow.slotCancelled(saved.getId());return saved;} }